/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: draftOf, captureOf, modelOf, proposed, handle, albumArtist, memberArtist, record, candidate,
 *              reads, resolve, members
 *   Constants: session, operationId, revision
 * Tests
 *   - entries share an identity by MusicBrainz ID, else by name in any letter case; one name under two IDs is two identities, named after the first entry
 *   - Album entries bind by key only; a member entry binds by key, then by the ID its Artist keeps, then by its name or a found name, whatever the Credit's role
 *   - a member entry binds to a captured Artist whose saved name is decorated through either part, by name or a found name, after any whole-name match
 *   - bound entries naming different Artists make one conflicting identity; its unbound entries need an explicit choice and it is never preselected
 *   - the default selection covers only lists that may be applied and changed; a list holding two names equal in any letter case is never applicable
 *   - captured entries rebuild the list review context showed: entries only, each record's name and ID, and a phrase only before another entry
 *   - a decisions body is a bounded set of exact items, one per identity and at most one label, with candidates only for reuse and replace
 *   - a confirmation must show exactly the computed preselections and ID writes, in any order, each well formed
 *   - preselection: the record keeping an identity's ID is reused, create is preselected without a candidate, and a name or alias candidate needs an answer
 *   - a bound record is never preselected for another identity, and an identity's other credited names are read as names found for its ID
 *   - a stored decision applies only while its identity's handle, name and ID are current; a stale or malformed one is ignored, never applied or removed
 *   - a stored decision is read through its allowlisted keys: a key a later release added is never echoed, and a missing MusicBrainz ID reads as null
 *   - ID writes: a bound record without an ID records the entry's, one keeping another ID keeps it unless replaced, a holder blocks it, and colliding writes are flagged
 *   - two bound identities recording different IDs on one Artist, which no decision can answer, record none: the Artist keeps what it holds and nothing waits
 *   - a decided write colliding with automatic ones waits for its answer, while the automatic ones are dropped for every selection, so a subset never waits on a row it does not show
 *   - a list two of whose entries resolve to one Artist whatever is decided is never applicable: one bound by its identity elsewhere, or two of one identity
 *   - an identity shared by the Album and members creates one record named after its first entry, the same for one operation and new for another
 *   - the label is bound while it names the first label Organization, by name, kept ID or a found name; otherwise its decision or preselection decides
 *   - Credit plans and views: a member without Credits takes its own entries and becomes documented, the Album lists the members still naming a replaced primary
 * @end-catalog */

/**
 * Identities of an existing-Album review without a database (adminCatalogReviewIdentity.ts): how entries of the Album and every
 * member group into identities and bind to captured records, which lists an apply may select, the shapes of decisions and of what
 * a confirmation showed, the preselections and MusicBrainz ID writes resolution computes from candidates and holders (injected
 * here), and the Credits and Credit views it implies. Every identity and name is synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import type { ClientSession } from 'mongodb';
// The database module loads first; importing the import service before it trips the index import cycle.
import '../../src/infrastructure/database';
import {
    capturedEntries, catalogReviewIdentityHandle, catalogReviewIdentityModel, defaultReviewSelection, parseReviewIdentityDecisions, parseShownIdWrites, parseShownPreselections,
    resolveCatalogReviewIdentities, reviewCreditPlans, reviewCreditViews, reviewFoundNames, sameShownIdWrites, sameShownPreselections, type ReviewIdentityReads, type ReviewSelection
} from '../../src/administration/catalog/adminCatalogReviewIdentity';
import type { ImportDuplicateCandidate } from '../../src/administration/import/adminImportContract';
import type { ImportArtistEntry, ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import type { CatalogReviewCapture } from '../../src/administration/catalog/adminCatalogReviewContract';
import { reviewId, reviewLookupDocument, reviewSlot, syntheticMbid, type ReviewMemberFixture } from '../support/catalogReviewLookupFixtures';

const session = {} as ClientSession, operationId = '0000000a-0000-4000-8000-0000000000a1', revision = 'e'.repeat(64);
const draftOf = (doc: AdminImportDocument) => doc.draft as ImportDraftV2 & { tracks: (ImportDraftV2['tracks'][number] & { artists: ImportArtistEntry[] })[] };
const captureOf = (doc: AdminImportDocument) => doc.catalogCapture as CatalogReviewCapture;
const modelOf = (doc: AdminImportDocument) => catalogReviewIdentityModel({ reviewId, slots: doc.manifest.files.map(file => file.slotId), draft: draftOf(doc), capture: doc.catalogCapture,
    found: reviewFoundNames(doc, draftOf(doc)) });
/** A proposed entry, as lookup writes one into the draft. */
const proposed = (key: number, name: string, musicBrainzId: string | null = null, role: 'primary' | 'featured' = 'primary', joinPhrase: string | null = null): ImportArtistEntry =>
    ({ key: `0000000d-0000-4000-8000-${String(key).padStart(12, '0')}`, name, role, joinPhrase, musicBrainzId });
const handle = (key: string) => catalogReviewIdentityHandle(reviewId, key);
const albumArtist = (index: number) => `0000000000000000000a${String(index + 1).padStart(4, '0')}`;
const memberArtist = (member: number, at: number) => `0000000000000000000b${String(member + 1).padStart(2, '0')}${String(at + 1).padStart(2, '0')}`;
const record = (n: number) => `00000000000000000000${String(n).padStart(4, '0')}`;
const candidate = (id: string, label: string, extra: Partial<ImportDuplicateCandidate> = {}): ImportDuplicateCandidate =>
    ({ kind: 'artist', id, label, revision, albumId: null, visibility: 'public', match: 'name', matchedSlotIds: [], automaticReuse: false, ...extra });
/** Injected reads: these candidates and holders (`kind:id` to record) and stored IDs (`kind:record` to ID); `drafts` records each synthetic draft read. */
function reads(items: ImportDuplicateCandidate[] = [], holders: [string, string][] = [], storedIds: [string, string | null][] = []) {
    const drafts: ImportDraftV2[] = [];
    const value: ReviewIdentityReads = { candidates: async input => { drafts.push(input.draft); return { items, memberMatchesComplete: true, unavailable: [] }; },
        holders: async () => ({ holders: new Map(holders), storedIds: new Map(storedIds) }) };
    return { drafts, value };
}
const resolve = (doc: AdminImportDocument, selection: ReviewSelection, fake = reads().value, decisions: unknown = doc.catalogIdentityDecisions, op: string | null = operationId) =>
    resolveCatalogReviewIdentities({ doc, draft: draftOf(doc), model: modelOf(doc), selection, decisions, operationId: op }, session, fake);
const members = (count: number, extra: (index: number) => ReviewMemberFixture = () => ({})) => Array.from({ length: count }, (_, index) => ({ durationMs: 60_000, trackNumber: index + 1, ...extra(index) }));

test('entries share an identity by MusicBrainz ID, else by name in any letter case; one name under two IDs is two identities, named after the first entry', () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic One', musicBrainzId: syntheticMbid(1) }], members: members(5) });
    const tracks = draftOf(doc).tracks;
    tracks[0].artists = [proposed(1, 'synthetic one', syntheticMbid(1))];
    tracks[1].artists = [proposed(2, 'Synthetic Uno', syntheticMbid(1))];
    tracks[2].artists = [proposed(3, 'Synthetic Two', syntheticMbid(2), 'primary', ' & '), proposed(4, 'Synthetic Three')];
    tracks[3].artists = [proposed(5, 'SYNTHETIC THREE')];
    tracks[4].artists = [proposed(6, 'Synthetic Two', syntheticMbid(3))];
    const model = modelOf(doc), rows = model.identities.map(identity => [identity.key, identity.name, identity.names, identity.entries.map(item => item.slotId), identity.state]);
    assert.deepEqual(rows, [
        // The Album's entry comes first and names the identity; its captured Credit binds every entry of the identity.
        [`id:${syntheticMbid(1)}`, 'Synthetic One', ['Synthetic Uno'], [null, reviewSlot(0), reviewSlot(1)], 'bound'],
        [`id:${syntheticMbid(2)}`, 'Synthetic Two', [], [reviewSlot(2)], 'unbound'],
        ['name:synthetic three', 'Synthetic Three', [], [reviewSlot(2), reviewSlot(3)], 'unbound'],
        [`id:${syntheticMbid(3)}`, 'Synthetic Two', [], [reviewSlot(4)], 'unbound']]);
    assert.deepEqual(model.identities[0].bound.map(item => item.id), [albumArtist(0)]);
    assert.deepEqual(model.identities.map(identity => identity.handle), model.identities.map(identity => handle(identity.key)));
});

test('Album entries bind by key only; a member entry binds by key, then by the ID its Artist keeps, then by its name or a found name, whatever the Credit\'s role', () => {
    const doc = reviewLookupDocument({ members: [
        { artists: [{ name: 'Member Singer' }] }, { otherCredits: ['composer'] }, { artists: [{ name: 'Old Name', musicBrainzId: syntheticMbid(5) }] },
        { artists: [{ name: 'Captured Alias' }] }, { artists: [{ name: 'Kept Singer' }] }] });
    doc.musicBrainzNames = [{ musicBrainzId: syntheticMbid(6), names: ['Captured Alias'] }];
    const draft = draftOf(doc);
    // An Album entry with a saved name but another key is a proposed entry, never bound by its name.
    draft.album.artists = [{ ...draft.album.artists[0], key: proposed(9, 'x').key }];
    draft.tracks[1].artists = [proposed(1, 'synthetic composer 2')];
    draft.tracks[2].artists = [proposed(2, 'New Name', syntheticMbid(5))];
    draft.tracks[3].artists = [proposed(3, 'Found Name', syntheticMbid(6))];
    draft.tracks[4].artists = [proposed(4, 'Someone Else')];
    const model = modelOf(doc), boundOf = (slot: string | null) => model.identities.flatMap(identity => identity.entries).find(item => item.slotId === slot)?.boundTo?.id ?? null;
    assert.deepEqual([boundOf(null), boundOf(reviewSlot(0)), boundOf(reviewSlot(1)), boundOf(reviewSlot(2)), boundOf(reviewSlot(3)), boundOf(reviewSlot(4))],
        [null, memberArtist(0, 0), '0000000000000000000d0201', memberArtist(2, 0), memberArtist(3, 0), null]);
    // A member's names found for an ID it carries are kept for reviews (the import bound never keeps them).
    assert.deepEqual([...model.found], [[syntheticMbid(6), ['Captured Alias']]]);
});

test('a member entry binds to a captured Artist whose saved name is decorated through either part, by name or a found name, after any whole-name match', () => {
    const doc = reviewLookupDocument({ members: members(3, () => ({ artists: [{ name: '合成情緒 -Gouseijoucho-' }] })) });
    doc.musicBrainzNames = [{ musicBrainzId: syntheticMbid(8), names: ['Gouseijoucho'] }];
    const tracks = draftOf(doc).tracks;
    tracks[0].artists = [proposed(5, '合成情緒')];
    tracks[1].artists = [proposed(6, 'Gouseijoucho Official', syntheticMbid(8))];
    tracks[2].artists = [proposed(7, 'Gouseijoucho Band')];
    const model = modelOf(doc), boundOf = (slot: string) => model.identities.flatMap(identity => identity.entries).find(item => item.slotId === slot)?.boundTo?.id ?? null;
    assert.deepEqual([boundOf(reviewSlot(0)), boundOf(reviewSlot(1)), boundOf(reviewSlot(2))], [memberArtist(0, 0), memberArtist(1, 0), null]);
    // A captured Artist saved under the entry's whole name is preferred to an earlier one that agrees only through a part.
    const both = reviewLookupDocument({ members: members(1, () => ({ artists: [{ name: '合成情緒 -Gouseijoucho-' }, { name: '合成情緒', role: 'featured' }] })) });
    draftOf(both).tracks[0].artists = [proposed(8, '合成情緒')];
    const bound = modelOf(both).identities.flatMap(identity => identity.entries).find(item => item.slotId === reviewSlot(0))?.boundTo?.id ?? null;
    assert.equal(bound, memberArtist(0, 1));
});

test('bound entries naming different Artists make one conflicting identity; its unbound entries need an explicit choice and it is never preselected', async () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Duo' }], members: members(2, index => index === 0 ? { artists: [{ name: 'synthetic duo' }] } : { attributionStatus: 'unknown' }) });
    draftOf(doc).tracks[1].artists = [proposed(1, 'Synthetic Duo')];
    const model = modelOf(doc), identity = model.identities[0];
    assert.deepEqual([model.identities.length, identity.state, identity.bound.map(item => item.id)], [1, 'conflicting', [albumArtist(0), memberArtist(0, 0)]]);
    const selection = { lists: [`tracks.${reviewSlot(1)}.artists`], label: false };
    // Even an exact candidate is never preselected for it: it needs an answer, and writes no ID.
    const resolved = await resolve(doc, selection, reads([candidate(record(1), 'Synthetic Duo')]).value);
    assert.deepEqual([resolved.preselections, resolved.needsAnswer, resolved.idWrites], [[], [identity.handle], []]);
    assert.deepEqual(resolved.entries.get(`tracks.${reviewSlot(1)}.artists`)?.map(item => item.subjectId), [null]);
    // A decision answers it; the bound entries keep their own Artists.
    const decided = await resolve(doc, selection, reads().value, [{ scope: 'artist', identity: identity.handle, boundName: 'Synthetic Duo', boundMusicBrainzId: null, action: 'reuse', candidateId: albumArtist(0), candidateRevision: revision }]);
    assert.deepEqual([decided.needsAnswer, decided.entries.get(`tracks.${reviewSlot(1)}.artists`)?.map(item => item.subjectId)], [[], [albumArtist(0)]]);
    // A replace never applies to a conflicting identity.
    const replaced = await resolve(doc, selection, reads().value, [{ scope: 'artist', identity: identity.handle, boundName: 'Synthetic Duo', boundMusicBrainzId: null, action: 'replace', candidateId: albumArtist(0), candidateRevision: revision }]);
    assert.deepEqual(replaced.needsAnswer, [identity.handle]);
});

test('the default selection covers only lists that may be applied and changed; a list holding two names equal in any letter case is never applicable', () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Duo' }, { name: 'SYNTHETIC DUO' }],
        members: members(5, index => [{ artists: [{ name: 'Synthetic A' }] }, { complete: false }, {}, { artists: [{ name: 'Synthetic B' }] }, { attributionStatus: 'unknown' }][index]) });
    const tracks = draftOf(doc).tracks;
    tracks[0].artists = [proposed(1, 'Synthetic C')];
    tracks[1].artists = [proposed(2, 'Synthetic D')];
    tracks[4].artists = [proposed(3, 'Synthetic E')];
    draftOf(doc).album.label = { name: 'Another Label', musicBrainzId: null };
    const model = modelOf(doc);
    assert.deepEqual(model.lists.map(item => [item.slotId, item.applicable, item.changed, item.foldedDuplicate]), [
        // A capture from before such names were shown once: complete, but holding a case-only repeat.
        [null, false, false, true], [reviewSlot(0), true, true, false], [reviewSlot(1), false, true, false],
        // An empty member list is never applied; an unchanged one is not selected.
        [reviewSlot(2), false, false, false], [reviewSlot(3), true, false, false], [reviewSlot(4), true, true, false]]);
    assert.deepEqual(defaultReviewSelection(model), { lists: [`tracks.${reviewSlot(0)}.artists`, `tracks.${reviewSlot(4)}.artists`], label: true });
    // The case-only repeat is one identity bound to two Artists, which never crashes resolution.
    assert.equal(model.identities[0].state, 'conflicting');
    // A read-only label is never selected, nor an unchanged one.
    const other = reviewLookupDocument({ label: 'other' });
    draftOf(other).album.label = { name: 'Another Label', musicBrainzId: null };
    assert.deepEqual([defaultReviewSelection(modelOf(other)).label, defaultReviewSelection(modelOf(reviewLookupDocument())).label], [false, false]);
});

test('captured entries rebuild the list review context showed: entries only, each record\'s name and ID, and a phrase only before another entry', () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic A', joinPhrase: ' & ', musicBrainzId: syntheticMbid(1) }, { name: 'Synthetic B', role: 'featured' }] });
    assert.deepEqual(capturedEntries(captureOf(doc).album), draftOf(doc).album.artists);
    const credits = captureOf(doc).album.credits!;
    // A Credit without an entry key breaks adjacency; one whose record is not ready is no entry.
    credits.splice(1, 0, { ...credits[1], creditId: 'credit-performer', role: 'performer', entryKey: null });
    credits[2] = { ...credits[2], subject: null };
    assert.deepEqual(capturedEntries(captureOf(doc).album).map(entry => [entry.name, entry.joinPhrase, entry.musicBrainzId]), [['Synthetic A', null, syntheticMbid(1)]]);
    assert.deepEqual(capturedEntries({ credits: 'malformed' }), []);
});

test('a decisions body is a bounded set of exact items, one per identity and at most one label, with candidates only for reuse and replace', () => {
    const artist = { scope: 'artist', identity: handle('name:x'), boundName: 'Synthetic X', action: 'reuse', candidateId: record(1), candidateRevision: revision };
    const label = { scope: 'label', identity: null, boundName: 'Synthetic Label', action: 'create-distinct', candidateId: null, candidateRevision: null };
    assert.deepEqual(parseReviewIdentityDecisions([artist, label]), [artist, label]);
    assert.deepEqual(parseReviewIdentityDecisions([{ ...artist, identity: artist.identity.toUpperCase() }])[0].identity, artist.identity);
    assert.equal(parseReviewIdentityDecisions(Array.from({ length: 513 }, (_, index) => ({ ...artist, identity: handle(`name:${index}`) }))).length, 513);
    for (const value of [null, {}, [null], Array.from({ length: 514 }, (_, index) => ({ ...artist, identity: handle(`name:${index}`) })), [artist, artist], [label, label], [{ ...artist, extra: 1 }],
        [{ scope: artist.scope, identity: artist.identity, boundName: artist.boundName, action: artist.action, candidateId: artist.candidateId }], [{ ...artist, scope: 'album' }],
        [{ ...artist, identity: null }], [{ ...label, identity: artist.identity }], [{ ...artist, identity: 'x' }], [{ ...artist, boundName: 'x'.repeat(201) }], [{ ...artist, boundName: null }],
        [{ ...artist, action: 'skip' }], [{ ...artist, candidateId: null }], [{ ...artist, candidateRevision: 'E'.repeat(64) }], [{ ...label, candidateId: record(1) }],
        [{ ...artist, action: 'replace', candidateRevision: null }], [{ ...artist, boundName: { nested: true } }]]) {
        assert.throws(() => parseReviewIdentityDecisions(value), JSON.stringify(value)?.slice(0, 80));
    }
});

test('a confirmation must show exactly the computed preselections and ID writes, in any order, each well formed', () => {
    const reuse = { scope: 'artist' as const, identity: handle('name:x'), boundName: 'Synthetic X', action: 'reuse' as const, candidateId: record(1), candidateRevision: revision };
    const create = { scope: 'label' as const, identity: null, boundName: 'Synthetic Label', action: 'create-distinct' as const, candidateId: null, candidateRevision: null };
    assert.ok(sameShownPreselections([create, reuse], [reuse, create]));
    assert.ok(sameShownPreselections([], []));
    for (const shown of [[reuse], [reuse, create, reuse], [reuse, { ...create, boundName: 'Other' }], [reuse, { ...create, extra: 1 }], [reuse, { ...create, action: 'replace' }],
        [{ ...reuse, candidateRevision: 'f'.repeat(64) }, create], [{ ...reuse, identity: reuse.identity.toUpperCase() }, create]]) assert.equal(sameShownPreselections(shown, [reuse, create]), false, JSON.stringify(shown));
    const write = { scope: 'artist' as const, identity: handle('name:x'), musicBrainzId: syntheticMbid(1), replaces: null }, replace = { scope: 'label' as const, identity: null, musicBrainzId: syntheticMbid(2), replaces: syntheticMbid(3) };
    assert.ok(sameShownIdWrites([replace, write], [write, replace]));
    for (const shown of [[write], [write, write, replace], [write, { ...replace, replaces: null }], [write, { ...replace, replaces: syntheticMbid(2) }], [write, { ...replace, identity: write.identity }]]) {
        assert.equal(sameShownIdWrites(shown, [write, replace]), false, JSON.stringify(shown));
    }
    assert.deepEqual([parseShownPreselections([reuse]), parseShownIdWrites([write])], [[reuse], [write]]);
    for (const raw of [null, [null], [{ ...write, scope: 'album' }], Array.from({ length: 514 }, () => write)]) assert.throws(() => parseShownIdWrites(raw));
    assert.throws(() => parseShownPreselections([{ ...reuse, candidateId: null }]));
});

test('preselection: the record keeping an identity\'s ID is reused, create is preselected without a candidate, and a name or alias candidate needs an answer', async () => {
    const doc = reviewLookupDocument({ members: members(4, () => ({ attributionStatus: 'unknown' })) });
    const tracks = draftOf(doc).tracks;
    tracks[0].artists = [proposed(1, 'Exact Artist', syntheticMbid(1))];
    tracks[1].artists = [proposed(2, 'New Artist', syntheticMbid(2))];
    tracks[2].artists = [proposed(3, 'Aliased Artist', syntheticMbid(3))];
    tracks[3].artists = [proposed(4, 'Named Artist')];
    const model = modelOf(doc), selection = defaultReviewSelection(model), handles = model.identities.slice(2).map(identity => identity.handle);
    // The holder of the first ID is a candidate and, as the database reads it, holds that ID.
    const fake = reads([candidate(record(1), 'Holder', { match: 'musicBrainzId', musicBrainzId: syntheticMbid(1) }), candidate(record(2), 'Alias', { match: 'alias', aliasOf: syntheticMbid(3) }),
        candidate(record(3), 'named artist')], [[`artist:${syntheticMbid(1)}`, record(1)]], [[`artist:${record(1)}`, syntheticMbid(1)]]);
    const resolved = await resolve(doc, selection, fake.value);
    // Only unbound identities are read, as one synthetic entry each (the Album's captured entries are bound).
    assert.deepEqual(fake.drafts[0].album.artists.map(entry => [entry.key, entry.name, entry.musicBrainzId]),
        model.identities.filter(identity => identity.state === 'unbound').map(identity => [identity.handle, identity.name, identity.musicBrainzId]));
    assert.deepEqual(resolved.preselections, [
        { scope: 'artist', identity: handles[0], boundName: 'Exact Artist', action: 'reuse', candidateId: record(1), candidateRevision: revision },
        { scope: 'artist', identity: handles[1], boundName: 'New Artist', action: 'create-distinct', candidateId: null, candidateRevision: null }]);
    assert.deepEqual(resolved.needsAnswer, [handles[2], handles[3]]);
    // The created Artist records its ID; the reused holder already keeps it.
    assert.deepEqual(resolved.idWrites, [{ scope: 'artist', identity: handles[1], musicBrainzId: syntheticMbid(2), replaces: null }]);
    assert.deepEqual(resolved.creates.map(item => [item.kind, item.name, item.musicBrainzId]), [['artist', 'New Artist', syntheticMbid(2)]]);
});

test('a bound record is never preselected for another identity, and an identity\'s other credited names are read as names found for its ID', async () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], members: members(2, () => ({ attributionStatus: 'unknown' })) });
    const tracks = draftOf(doc).tracks;
    tracks[0].artists = [proposed(1, 'Track Artist', syntheticMbid(7))];
    tracks[1].artists = [proposed(2, 'Track Artist Alias', syntheticMbid(7))];
    const fake = reads([candidate(albumArtist(0), 'Synthetic Ensemble', { match: 'musicBrainzId', musicBrainzId: syntheticMbid(7) })]);
    const resolved = await resolve(doc, defaultReviewSelection(modelOf(doc)), fake.value);
    const identity = modelOf(doc).identities.find(item => item.musicBrainzId === syntheticMbid(7))!;
    assert.deepEqual([resolved.preselections, resolved.needsAnswer], [[], [identity.handle]]);
    let names: ReadonlyMap<string, readonly string[]> | undefined;
    await resolveCatalogReviewIdentities({ doc, draft: draftOf(doc), model: modelOf(doc), selection: defaultReviewSelection(modelOf(doc)), decisions: [], operationId },
        session, { ...fake.value, candidates: async input => { names = input.names; return { items: [], memberMatchesComplete: true, unavailable: [] }; } });
    assert.deepEqual(names?.get(syntheticMbid(7)), ['Track Artist Alias']);
});

test('a stored decision applies only while its identity\'s handle, name and ID are current; a stale or malformed one is ignored, never applied or removed', async () => {
    const doc = reviewLookupDocument({ members: members(1, () => ({ attributionStatus: 'unknown' })) });
    draftOf(doc).tracks[0].artists = [proposed(1, 'Named Artist', syntheticMbid(40))];
    const model = modelOf(doc), selection = defaultReviewSelection(model), identity = model.identities.find(item => item.musicBrainzId === syntheticMbid(40))!;
    // A name candidate: without a decision the identity needs an answer; a current create decision answers it.
    const fake = reads([candidate(record(1), 'Named Artist')]);
    const decision = { scope: 'artist', identity: identity.handle, boundName: 'Named Artist', boundMusicBrainzId: syntheticMbid(40), action: 'create-distinct', candidateId: null, candidateRevision: null };
    assert.deepEqual((await resolve(doc, selection, fake.value, [])).needsAnswer, [identity.handle]);
    const decided = await resolve(doc, selection, fake.value, [decision]);
    assert.deepEqual([decided.needsAnswer, decided.creates.map(item => [item.name, item.musicBrainzId]), decided.scoped.find(item => item.identity.handle === identity.handle)?.outcome.decision],
        [[], [['Named Artist', syntheticMbid(40)]], decision]);
    // Made for another name, ID or identity, or unreadable: the identity needs an answer again, and the stored set is left as it is.
    for (const value of [{ ...decision, boundName: 'Named Artist Earlier' }, { ...decision, boundMusicBrainzId: syntheticMbid(41) }, { ...decision, boundMusicBrainzId: null },
        { ...decision, identity: handle('name:other') }, { ...decision, action: 'skip' }, { ...decision, candidateId: record(1) }, null, 'malformed']) {
        const stored = [value], snapshot = structuredClone(stored), resolved = await resolve(doc, selection, fake.value, stored);
        assert.deepEqual([resolved.needsAnswer, resolved.creates], [[identity.handle], []], JSON.stringify(value));
        assert.deepEqual(stored, snapshot);
    }
});

test('a stored decision is read through its allowlisted keys: a key a later release added is never echoed, and a missing MusicBrainz ID reads as null', async () => {
    const doc = reviewLookupDocument({ members: members(1, () => ({ attributionStatus: 'unknown' })) });
    draftOf(doc).tracks[0].artists = [proposed(1, 'Plain Artist')];
    const identity = modelOf(doc).identities.find(item => item.name === 'Plain Artist')!;
    const stored = { scope: 'artist', identity: identity.handle, boundName: 'Plain Artist', action: 'create-distinct', candidateId: null, candidateRevision: null, laterKey: 'kept by a later release' };
    const resolved = await resolve(doc, defaultReviewSelection(modelOf(doc)), reads().value, [stored]);
    const decision = resolved.scoped.find(item => item.identity.handle === identity.handle)!.outcome.decision;
    assert.deepEqual(decision, { scope: 'artist', identity: identity.handle, boundName: 'Plain Artist', boundMusicBrainzId: null, action: 'create-distinct', candidateId: null, candidateRevision: null });
    assert.deepEqual(Object.keys(decision!), ['scope', 'identity', 'boundName', 'boundMusicBrainzId', 'action', 'candidateId', 'candidateRevision']);
});

test('ID writes: a bound record without an ID records the entry\'s, one keeping another ID keeps it unless replaced, a holder blocks it, and colliding writes are flagged', async () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic A' }, { name: 'Synthetic B', musicBrainzId: syntheticMbid(20) }] });
    for (const credit of captureOf(doc).album.credits!) if (credit.subject) credit.subject.revision = revision;
    const draft = draftOf(doc);
    draft.album.artists = draft.album.artists.map((entry, index) => ({ ...entry, musicBrainzId: syntheticMbid(index + 1) }));
    const selection = { lists: ['album.artists'], label: false }, model = modelOf(doc), [a, b] = model.identities;
    const resolved = await resolve(doc, selection);
    // A records its entry's ID; B keeps the ID its Artist keeps, so nothing is written for it.
    assert.deepEqual(resolved.idWrites, [{ scope: 'artist', identity: a.handle, musicBrainzId: syntheticMbid(1), replaces: null }]);
    assert.deepEqual(resolved.writes, [{ kind: 'artist', recordId: albumArtist(0), musicBrainzId: syntheticMbid(1), replaces: null, created: false }]);
    // An explicit replace on B's bound record replaces its ID.
    const replace = { scope: 'artist', identity: b.handle, boundName: 'Synthetic B', boundMusicBrainzId: syntheticMbid(2), action: 'replace', candidateId: albumArtist(1), candidateRevision: revision };
    assert.deepEqual((await resolve(doc, selection, reads().value, [replace])).idWrites[1], { scope: 'artist', identity: b.handle, musicBrainzId: syntheticMbid(2), replaces: syntheticMbid(20) });
    // A decision made for another ID or name binds nothing.
    assert.equal((await resolve(doc, selection, reads().value, [{ ...replace, boundMusicBrainzId: null }])).idWrites.length, 1);
    // Another record holding the ID blocks recording it.
    assert.deepEqual((await resolve(doc, selection, reads([], [[`artist:${syntheticMbid(1)}`, record(9)]]).value)).idWrites, []);
    // A replace whose new ID another record holds is invalid: its row shows its decision again, needing an answer, and writes nothing.
    const invalid = await resolve(doc, selection, reads([], [[`artist:${syntheticMbid(2)}`, record(9)]]).value, [replace]);
    const row = invalid.scoped.find(item => item.identity.handle === b.handle)!.outcome;
    assert.deepEqual([invalid.invalidWrite, invalid.invalidDecisions, invalid.needsAnswer, row.decision?.action, row.needsAnswer, row.write], [true, [b.handle], [b.handle], 'replace', true, null]);
    // Two identities of different lists reusing one record by decision, each writing an ID, collide: both rows need an answer.
    const twice = reviewLookupDocument({ members: members(2, () => ({ attributionStatus: 'unknown' })) });
    draftOf(twice).tracks[0].artists = [proposed(1, 'Synthetic P', syntheticMbid(30))];
    draftOf(twice).tracks[1].artists = [proposed(2, 'Synthetic Q', syntheticMbid(31))];
    const identities = modelOf(twice).identities.filter(identity => identity.state === 'unbound');
    const decisions = identities.map(identity => ({ scope: 'artist', identity: identity.handle, boundName: identity.name, boundMusicBrainzId: identity.musicBrainzId, action: 'reuse', candidateId: record(5), candidateRevision: revision }));
    const collided = await resolve(twice, defaultReviewSelection(modelOf(twice)), reads([], [], [[`artist:${record(5)}`, null]]).value, decisions);
    assert.deepEqual([collided.idWrites.length, collided.idWriteCollision, collided.duplicateInList, collided.reuseTargets.length], [2, true, false, 2]);
    assert.deepEqual([collided.needsAnswer, collided.collidingDecisions], [identities.map(identity => identity.handle), identities.map(identity => identity.handle)]);
    assert.deepEqual(collided.reuseTargets.map(target => target.owner), identities.map(identity => identity.handle));
});

test('two bound identities recording different IDs on one Artist, which no decision can answer, record none: the Artist keeps what it holds and nothing waits', async () => {
    // The Album's entry is captured from an Artist keeping no ID and gains one; a member's captured Credit names that same Artist,
    // and its own track credits the name under another ID, so the member's entry binds to that Artist by name.
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Shared' }], members: [{ artists: [{ name: 'Synthetic Shared' }] }] });
    captureOf(doc).members[0].credits![0].subjectId = albumArtist(0);
    draftOf(doc).album.artists = draftOf(doc).album.artists.map(entry => ({ ...entry, musicBrainzId: syntheticMbid(1) }));
    draftOf(doc).tracks[0].artists = [proposed(1, 'Synthetic Shared', syntheticMbid(2))];
    const model = modelOf(doc), selection = defaultReviewSelection(model);
    assert.deepEqual([model.identities.map(identity => [identity.state, identity.bound.map(item => item.id)]), selection.lists],
        [[['bound', [albumArtist(0)]], ['bound', [albumArtist(0)]]], ['album.artists', `tracks.${reviewSlot(0)}.artists`]]);
    const resolved = await resolve(doc, selection);
    assert.deepEqual([resolved.idWrites, resolved.writes, resolved.idWriteCollision, resolved.needsAnswer, resolved.scoped.map(item => item.outcome.write)], [[], [], false, [], [null, null]]);
    // Selected alone, each list writes what the default shows for its identities: nothing, so a confirmation that deselects the
    // other list applies as shown.
    for (const lists of [['album.artists'], [`tracks.${reviewSlot(0)}.artists`]]) {
        const alone = await resolve(doc, { lists, label: false }), handles = new Set(alone.scoped.map(item => item.identity.handle));
        assert.deepEqual([alone.idWrites, alone.writes, alone.needsAnswer, alone.idWriteCollision], [resolved.idWrites.filter(write => handles.has(write.identity!)), [], [], false], lists[0]);
    }
});

test('a decided write colliding with automatic ones waits for its answer, while the automatic ones are dropped for every selection, so a subset never waits on a row it does not show', async () => {
    // Two bound identities record different IDs on the Album's Artist (dropped as above); a third, in another member, is decided to
    // reuse that same Artist, which keeps no ID, and would record its own.
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Shared' }], members: [{ artists: [{ name: 'Synthetic Shared' }] }, { attributionStatus: 'unknown' }] });
    captureOf(doc).members[0].credits![0].subjectId = albumArtist(0);
    draftOf(doc).album.artists = draftOf(doc).album.artists.map(entry => ({ ...entry, musicBrainzId: syntheticMbid(1) }));
    draftOf(doc).tracks[0].artists = [proposed(1, 'Synthetic Shared', syntheticMbid(2))];
    draftOf(doc).tracks[1].artists = [proposed(2, 'Synthetic Decided', syntheticMbid(3))];
    const model = modelOf(doc), selection = defaultReviewSelection(model), decided = model.identities.find(identity => identity.musicBrainzId === syntheticMbid(3))!;
    const decisions = [{ scope: 'artist', identity: decided.handle, boundName: 'Synthetic Decided', boundMusicBrainzId: syntheticMbid(3), action: 'reuse', candidateId: albumArtist(0), candidateRevision: revision }];
    const fake = reads([], [], [[`artist:${albumArtist(0)}`, null]]).value, all = await resolve(doc, selection, fake, decisions);
    assert.deepEqual([all.idWrites.map(write => write.identity), all.needsAnswer, all.collidingDecisions, all.idWriteCollision], [[decided.handle], [decided.handle], [decided.handle], false]);
    // Every subset writes and waits exactly as the default shows for the identities it selects.
    for (const lists of [['album.artists'], [`tracks.${reviewSlot(0)}.artists`], ['album.artists', `tracks.${reviewSlot(0)}.artists`], [`tracks.${reviewSlot(1)}.artists`]]) {
        const subset = await resolve(doc, { lists, label: false }, fake, decisions), handles = new Set(subset.scoped.map(item => item.identity.handle));
        assert.deepEqual([subset.idWrites, subset.needsAnswer, subset.idWriteCollision], [all.idWrites.filter(write => handles.has(write.identity!)), all.needsAnswer.filter(handle => handles.has(handle)), false],
            lists.join());
    }
});

test('a list two of whose entries resolve to one Artist whatever is decided is never applicable: one bound by its identity elsewhere, or two of one identity', () => {
    // The Album credits its Artist, and a member credits that same Artist under another name its own track gives an ID; the Album's
    // new entry of that name and ID is bound through the member, so the Album's list would name one Artist twice.
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Shared' }], members: [{ artists: [{ name: 'Synthetic Alias' }] }] });
    captureOf(doc).members[0].credits![0].subjectId = albumArtist(0);
    draftOf(doc).tracks[0].artists = draftOf(doc).tracks[0].artists.map(entry => ({ ...entry, musicBrainzId: syntheticMbid(5) }));
    draftOf(doc).album.artists = [...draftOf(doc).album.artists, proposed(1, 'Synthetic Alias', syntheticMbid(5))];
    const model = modelOf(doc);
    assert.deepEqual(model.lists.map(item => [item.slotId, item.repeatsArtist, item.applicable, item.changed]), [[null, true, false, true], [reviewSlot(0), false, true, true]]);
    assert.deepEqual(defaultReviewSelection(model).lists, [`tracks.${reviewSlot(0)}.artists`]);
    // Two new entries carrying one ID are one identity, so any answer names one Artist for both.
    const same = reviewLookupDocument({ albumEntries: [] });
    draftOf(same).album.artists = [proposed(1, 'Synthetic First', syntheticMbid(6)), proposed(2, 'Synthetic Second', syntheticMbid(6))];
    assert.deepEqual(modelOf(same).lists.map(item => [item.repeatsArtist, item.applicable]), [[true, false]]);
    // Entries bound to different Artists, or of different identities none of them bound, may be applied.
    const distinct = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Shared' }] });
    draftOf(distinct).album.artists = [...draftOf(distinct).album.artists, proposed(1, 'Synthetic New', syntheticMbid(7)), proposed(2, 'Synthetic Newer', syntheticMbid(8))];
    assert.deepEqual(modelOf(distinct).lists.map(item => [item.repeatsArtist, item.applicable]), [[false, true]]);
});

test('an identity shared by the Album and members creates one record named after its first entry, the same for one operation and new for another', async () => {
    const doc = reviewLookupDocument({ albumEntries: [], members: members(3, () => ({ attributionStatus: 'unknown' })) });
    draftOf(doc).album.artists = [proposed(1, 'Shared Artist')];
    for (const [index, track] of draftOf(doc).tracks.entries()) track.artists = [proposed(10 + index, index ? 'SHARED ARTIST' : 'shared artist')];
    const selection = defaultReviewSelection(modelOf(doc)), first = await resolve(doc, selection), again = await resolve(doc, selection);
    assert.deepEqual([first.creates.length, first.creates[0].name], [1, 'Shared Artist']);
    const subjects = [...first.entries.values()].map(items => items[0].subjectId);
    assert.deepEqual([new Set(subjects).size, subjects[0], again.creates[0].id], [1, first.creates[0].id, first.creates[0].id]);
    assert.notEqual((await resolve(doc, selection, reads().value, [], '0000000a-0000-4000-8000-0000000000a2')).creates[0].id, first.creates[0].id);
    // One list resolving one Artist twice is flagged, and each identity behind it needs an answer.
    draftOf(doc).album.artists = [proposed(1, 'Shared Artist'), proposed(2, 'Other Artist')];
    const other = modelOf(doc).identities.find(identity => identity.name === 'Other Artist')!, shared = modelOf(doc).identities[0];
    const decisions = [other, shared].map(identity => ({ scope: 'artist', identity: identity.handle, boundName: identity.name, boundMusicBrainzId: null, action: 'reuse', candidateId: record(5), candidateRevision: revision }));
    const duplicated = await resolve(doc, defaultReviewSelection(modelOf(doc)), reads().value, decisions);
    assert.deepEqual([duplicated.duplicateInList, [...duplicated.needsAnswer].sort()], [true, [other.handle, shared.handle].sort()]);
});

test('the label is bound while it names the first label Organization, by name, kept ID or a found name; otherwise its decision or preselection decides', async () => {
    const bound = reviewLookupDocument();
    draftOf(bound).album.label = { name: 'SYNTHETIC LABEL', musicBrainzId: syntheticMbid(40) };
    let model = modelOf(bound);
    assert.deepEqual([model.label.bound?.id, model.label.changed, defaultReviewSelection(model).label], ['0000000000000000000c0001', true, true]);
    const labelOnly = { lists: [], label: true };
    // A bound label records the ID on its Organization.
    assert.deepEqual((await resolve(bound, labelOnly)).idWrites, [{ scope: 'label', identity: null, musicBrainzId: syntheticMbid(40), replaces: null }]);
    bound.musicBrainzNames = [{ musicBrainzId: syntheticMbid(40), names: ['Synthetic Label'] }];
    draftOf(bound).album.label = { name: 'Renamed Label', musicBrainzId: syntheticMbid(40) };
    assert.equal(modelOf(bound).label.bound?.id, '0000000000000000000c0001');
    // A label naming another Organization is unbound: created without a candidate, else it needs an answer.
    const other = reviewLookupDocument({ label: 'none' });
    draftOf(other).album.label = { name: 'Looked Up Label', musicBrainzId: null };
    model = modelOf(other);
    assert.deepEqual([model.label.bound, model.label.applicable, model.label.changed], [null, true, true]);
    const created = await resolve(other, labelOnly);
    assert.deepEqual([created.preselections.map(item => [item.scope, item.action]), created.creates.map(item => [item.kind, item.name])], [[['label', 'create-distinct']], [['organization', 'Looked Up Label']]]);
    const asked = await resolve(other, labelOnly, reads([candidate(record(7), 'Looked Up Label', { kind: 'organization' })]).value);
    assert.deepEqual([asked.preselections, asked.needsAnswer, asked.labelSubject], [[], ['label'], null]);
    const decided = await resolve(other, labelOnly, reads().value, [{ scope: 'label', identity: null, boundName: 'Looked Up Label', boundMusicBrainzId: null, action: 'reuse', candidateId: record(7), candidateRevision: revision }]);
    assert.deepEqual([decided.needsAnswer, decided.labelSubject, decided.reuseTargets], [[], record(7), [{ kind: 'organization', id: record(7), revision, owner: 'label' }]]);
});

test('Credit plans and views: a member without Credits takes its own entries and becomes documented, the Album lists the members still naming a replaced primary', async () => {
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Old' }], members: [{ artists: [{ name: 'Synthetic Old' }] }, { attributionStatus: 'unknown', otherCredits: ['composer'] }] });
    // The first member credits the Album's primary Artist itself.
    captureOf(doc).members[0].credits![0].subjectId = albumArtist(0);
    const draft = draftOf(doc);
    draft.album.artists = [proposed(1, 'Synthetic New')];
    draft.tracks[1].artists = [proposed(2, 'Track Singer')];
    const model = modelOf(doc), selection = defaultReviewSelection(model), resolved = await resolve(doc, selection, reads().value, [], null);
    assert.deepEqual(selection.lists, ['album.artists', `tracks.${reviewSlot(1)}.artists`]);
    const plans = reviewCreditPlans(model, resolved, selection, operationId);
    assert.deepEqual(plans.members.get(reviewSlot(1))?.next.map(credit => [credit.role, credit.order]), [['primary', 0], ['composer', 1]]);
    assert.equal(plans.album?.changes, true);
    const names = new Map(resolved.creates.map(item => [`${item.kind}:${item.id}`, item.name]));
    const views = reviewCreditViews(model, resolved, selection, names);
    // Records still to be created and new Credits show no IDs; the replaced primary is still named by the first member.
    const created = model.identities.find(identity => identity.name === 'Synthetic New')!.handle;
    assert.deepEqual(views.album?.next.map(credit => [credit.name, credit.subjectId, credit.creditId, credit.identity]),
        [['Synthetic New', null, null, created], ['Synthetic Label', '0000000000000000000c0001', 'credit-label', null]]);
    assert.deepEqual(views.album?.current.map(credit => [credit.name, credit.subjectId, credit.creditId]),
        [['Synthetic Old', albumArtist(0), 'credit-0'], ['Synthetic Label', '0000000000000000000c0001', 'credit-label']]);
    assert.deepEqual([views.album?.replacedPrimaryArtistIds, views.album?.membersNamingReplaced], [[albumArtist(0)], [reviewSlot(0)]]);
    assert.deepEqual(views.members.map(item => [item.slotId, item.credits, item.attribution, item.removedCreditIds, item.next.map(credit => credit.name)]),
        [[reviewSlot(1), true, { from: 'unknown', to: 'documented' }, [], ['Track Singer', 'Synthetic Composer 2']]]);
    // A list changed only in MusicBrainz IDs changes no Credit.
    const ids = reviewLookupDocument({ members: [{ artists: [{ name: 'Member Singer' }] }] });
    draftOf(ids).tracks[0].artists = draftOf(ids).tracks[0].artists.map(entry => ({ ...entry, musicBrainzId: syntheticMbid(3) }));
    const idModel = modelOf(ids), idSelection = defaultReviewSelection(idModel), idResolved = await resolve(ids, idSelection);
    assert.deepEqual([idSelection.lists, reviewCreditPlans(idModel, idResolved, idSelection, operationId).members.get(reviewSlot(0))?.changes, idResolved.idWrites.length],
        [[`tracks.${reviewSlot(0)}.artists`], false, 1]);
});
